import json,pathlib
p=pathlib.Path(__file__).with_name('americas.json')
a=json.loads(p.read_text()); rows={r['code']:r for r in a}
def setrow(code,status,rule,scope,authority,urls,question='',limit=None,attempts=None):
 r=rows[code];r.update(status=status,rule=rule,personalMailApplicability=scope,quantityLimit=limit,authority=authority,evidenceUrls=urls,remainingQuestion=question,researchAttempts=attempts or ['Checked destination authority agricultural guidance, processed-tea classification and personal/postal applicability.'])
def save():p.write_text(json.dumps(list(rows.values()),indent=2,ensure_ascii=False)+'\n')
