setrow('PA','conditional','Panama Resolution 055-2016 admits commercially manufactured, labelled dehydrated plant parts without plant-health certification. Personal mail requires an approved online personal-consumption notification, ID and invoice before entry. Maximum 5 kg per person or 10 kg per family; no more than three postal/courier notifications yearly.','Article 6 explicitly covers private or public messaging/postal services, and applies the weight caps to both travelers and such shipments.','Panama Agencia Panameña de Alimentos',['https://sit.apa.gob.pa/aupsa/requisitos/RES055_2016MuestraConsumoPersonalEventosDonacionesTODOS.pdf','https://sit.apa.gob.pa/ConsumoPersonal/login.aspx?AspxAutoDetectCookieSupport=1','https://apa.gob.pa/la-apa-te-informa-sobre-los-alimentos-que-pueden-ingresar-losviajeros-a-traves-del-aeropuerto-internacional-de-tocumen/'],limit={'netGrams':5000,'inclusive':True,'max100gBags':50,'scope':'All personal food in a consignment per person; 10000 g per family; no more than 3 postal/courier notifications per year.','kind':'personal food exemption limit'})
